'use strict';

// The 2000 bots that fill arenas. Generated by scripts/generate_bot_pool.js;
// the app ships the same list (assets/data/bots.json) for its matchmaking
// fallback. Every bot is shown with a "BOT" badge and has no users/ document,
// so bots never appear in the world ranking.

const RAW = require('./bot_pool.json');

const GAME_INDEX = { chess: 2, checkers: 3, domino: 4 };

/** uid → bot, uids are bot_0001 … bot_2000. */
const POOL = RAW.map((row, i) => ({
  uid: `bot_${String(i + 1).padStart(4, '0')}`,
  username: row[0],
  countryCode: row[1],
  ratings: { chess: row[2], checkers: row[3], domino: row[4] },
}));

function ratingFor(bot, gameType) {
  return bot.ratings[gameType] ?? bot.ratings.chess;
}

/**
 * [count] random bots for [gameType] whose uids are not in [takenUids], as
 * the small records stored on an arena ({uid, username, rating, countryCode}).
 */
function pickBots(gameType, count, takenUids = new Set(), rand = Math.random) {
  const game = GAME_INDEX[gameType] ? gameType : 'chess';
  const record = (bot) => ({
    uid: bot.uid,
    username: bot.username,
    rating: ratingFor(bot, game),
    countryCode: bot.countryCode,
  });
  const want = Math.max(0, Math.min(count, POOL.length));
  if (want === 0) return [];

  // Mostly taken (a huge arena): draw from what is left.
  if (takenUids.size > POOL.length / 2) {
    const free = POOL.filter((b) => !takenUids.has(b.uid));
    for (let i = free.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [free[i], free[j]] = [free[j], free[i]];
    }
    return free.slice(0, want).map(record);
  }

  // Usual case: a few dozen out of 2000, so random draws rarely collide.
  const out = [];
  const seen = new Set(takenUids);
  while (out.length < want) {
    const bot = POOL[Math.floor(rand() * POOL.length)];
    if (seen.has(bot.uid)) continue;
    seen.add(bot.uid);
    out.push(record(bot));
  }
  return out;
}

module.exports = { POOL, pickBots, ratingFor };
